{
  "nodes": [
    {
      "id": "Start",
      "text": "The tavern door creaks open. Smoke and laughter fill the air.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "TavernEntry",
      "text": "Three figures catch your eye: a hooded stranger, a boisterous merchant, and the barkeep.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "TavernChoice",
      "text": "Approach the hooded stranger.\nSit next to the merchant.\nOrder a drink from the barkeep.\n[Observe] Study the room from the shadows.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "ObserveRoom",
      "text": "You notice the stranger slipping a note to the barkeep. The merchant counts gold nervously.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "ObserveChoice",
      "text": "Intercept the note.\nPickpocket the merchant.\nPretend you saw nothing.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "InterceptNote",
      "text": "You dare?!",
      "speaker": "Stranger",
      "type": "line"
    },
    {
      "id": "PickpocketAttempt",
      "text": "[Sleight of Hand] Swiftly grab the pouch.\n[Distraction] Bump into him accidentally.\nAbandon the attempt.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "PickpocketSuccess",
      "text": "50 gold pieces heavier, you slip away. The merchant hasn't noticed... yet.",
      "speaker": "Narrator",
      "type": "line"
    },
    {
      "id": "PickpocketDistract",
      "text": "Watch it, friend!",
      "speaker": "Merchant",
      "type": "line"
    },
    {
      "id": "MerchantAnnoyed",
      "text": "Apologize profusely.\n[Intimidate] You watch where YOU'RE going.\nUse the distraction to grab the gold.",
      "speaker": "",
      "type": "choice"
    },
    {
      "id": "MerchantCalm",
      "text": "Hmph. Buy me a drink and we're even.",
      "speaker": "Merchant",
      "type": "line"
    },
    {
      "id": "MerchantFight",
      "text": "Why you little—!",
      "speaker": "Merchant",
      "type": "line"
    },
    {
      "id": "PickpocketAfter",
      "text": "But where to spend your ill-gotten gains?",
      "speaker": "Narrator",
      "type": "line"
    },

